function formatFeedbackText(question, answer, index) {
  const explanation = answer.correct
    ? `Correct. ${question.correct_explanation}`
    : `Not quite. ${question.wrong_explanation}`;
  if (index < displayedQuestions.length - 1) return explanation;
  return `${explanation} Quiz complete. You can use the Reset or Randomize buttons to start over, or the Previous and Next navigation to review what you did.`;
}

function buildFeedbackPanel(question, response, index = currentQuestionIndex) {
  const answer = question.answers[response.answerIndex];
  const panel = document.createElement("div");
  panel.className = "feedback";
  panel.dataset.correct = String(answer.correct);
  panel.setAttribute("aria-hidden", "true");
  const explanation = document.createElement("p");
  explanation.textContent = answer.correct
    ? `Correct. ${question.correct_explanation}`
    : `Not quite. ${question.wrong_explanation}`;
  panel.append(explanation);
  if (index >= displayedQuestions.length - 1) {
    const complete = document.createElement("p");
    complete.className = "quiz-complete";
    complete.textContent = "Quiz complete. You can use the Reset or Randomize buttons to start over, or the Previous and Next navigation to review what you did.";
    panel.append(complete);
  }
  return panel;
}

