const scoreText = document.querySelector("#quiz-score");
const completeBanner = document.querySelector("#quiz-complete");
const feedbackStack = document.querySelector("#quiz-feedback-stack");

function formatFeedbackText(question, answer) {
  return answer.correct
    ? `Correct. ${question.correct_explanation}`
    : `Not quite. ${question.wrong_explanation}`;
}

function buildFeedbackPanel(question, response) {
  const answer = question.answers[response.answerIndex];
  const panel = document.createElement("div");
  panel.className = "feedback";
  panel.dataset.correct = String(answer.correct);
  panel.setAttribute("aria-hidden", "true");
  const explanation = document.createElement("p");
  explanation.textContent = formatFeedbackText(question, answer);
  panel.append(explanation);
  return panel;
}

function announceFeedback(question, response) {
  feedback.textContent = response
    ? formatFeedbackText(question, question.answers[response.answerIndex])
    : "";
}

