input.command:
playwright-cli eval "async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  document.querySelector('#quiz')?.scrollIntoView({ block: 'start' });
  await sleep(300);
  const total = JSON.parse(document.querySelector('#explainer-quiz-data').textContent).questions.length;
  const before = {
    hidden: document.querySelector('#quiz-complete')?.hidden,
    inFeedback: Boolean(document.querySelector('#quiz-feedback-stack .quiz-complete')),
  };
  for (let i = 0; i < total; i += 1) {
    document.querySelector('#explainer-quiz button[data-answer-index]')?.click();
    await sleep(400);
    if (i < total - 1) {
      document.querySelector('#quiz-next')?.click();
      await sleep(900);
    }
  }
  const banner = document.querySelector('#quiz-complete');
  const feedback = document.querySelector('#quiz-feedback-stack .feedback');
  return {
    total,
    before,
    hidden: banner.hidden,
    parentClass: banner.parentElement.className,
    previous: banner.previousElementSibling?.className || banner.previousElementSibling?.id,
    next: banner.nextElementSibling?.className,
    inFeedback: Boolean(document.querySelector('#quiz-feedback-stack .quiz-complete')),
    bannerText: banner.textContent,
    feedbackText: feedback?.textContent?.slice(0, 180),
    emoji: banner.textContent.includes('🎉'),
  };
}"

